package za.co.football;

/**
 * An immutable record representing one completed football match.
 *
 * <p>A Java {@code record} is the right choice here because a match result is
 * pure data — it never changes after the final whistle. The compiler generates
 * {@code equals}, {@code hashCode}, and {@code toString} automatically.
 *
 * <p><strong>Validation rules (enforced in the compact constructor):</strong>
 * <ul>
 *   <li>Team names must not be null or blank (whitespace-only counts as blank).</li>
 *   <li>Home and away teams must be different (case-insensitive comparison).</li>
 *   <li>Goal counts must be zero or positive; negative goals are rejected.</li>
 * </ul>
 *
 * <p>Example:
 * <pre>
 *   MatchResult m = new MatchResult("Arsenal", "Chelsea", 2, 1);
 *   // Arsenal won 2-1 at home
 * </pre>
 *
 * @param homeTeam   name of the home side, as it appears in the CSV
 * @param awayTeam   name of the away side, as it appears in the CSV
 * @param homeGoals  goals scored by the home side (≥ 0)
 * @param awayGoals  goals scored by the away side (≥ 0)
 */
public record MatchResult(String homeTeam, String awayTeam, int homeGoals, int awayGoals) {

    /**
     * Compact constructor — runs automatically whenever a {@code MatchResult}
     * is created, including inside {@code CsvMatchReader}.
     *
     * <p>Using a compact constructor (no parameter list) means the record
     * fields are still assigned normally; we just add validation before that.
     */
    public MatchResult {
        if (homeTeam == null || homeTeam.isBlank()) {
            throw new IllegalArgumentException("Home team name must not be blank.");
        }
        if (awayTeam == null || awayTeam.isBlank()) {
            throw new IllegalArgumentException("Away team name must not be blank.");
        }
        if (homeTeam.trim().equalsIgnoreCase(awayTeam.trim())) {
            throw new IllegalArgumentException(
                    "A team cannot play against itself: \"" + homeTeam.trim() + "\".");
        }
        if (homeGoals < 0) {
            throw new IllegalArgumentException(
                    "Home goals cannot be negative, got: " + homeGoals);
        }
        if (awayGoals < 0) {
            throw new IllegalArgumentException(
                    "Away goals cannot be negative, got: " + awayGoals);
        }

        // Normalise team names: strip leading/trailing whitespace.
        // The record fields are assigned after this block completes.
        homeTeam = homeTeam.trim();
        awayTeam = awayTeam.trim();
    }
}

package za.co.football;

/**
 * Accumulates league statistics for a single team across multiple matches.
 *
 * <p>Each instance represents one row in the standings table — the kind you
 * would see printed in a 1974 newspaper. Start with a team name and all
 * counters at zero, then call {@link #update(int, int)} once for every match
 * the team played.
 *
 * <h2>Historical scoring rules (1974/75 English First Division)</h2>
 * <ul>
 *   <li><strong>Win  → 2 points</strong></li>
 *   <li><strong>Draw → 1 point</strong></li>
 *   <li><strong>Loss → 0 points</strong></li>
 * </ul>
 * The switch to 3 points for a win did not happen until the 1981/82 season.
 * Using the wrong value here would silently produce wrong standings, so this
 * policy is tested explicitly in {@code TeamStandingTest}.
 *
 * <h2>Goal average (not goal difference)</h2>
 * The Football League ranked tied teams by <em>goal average</em>
 * (goals scored ÷ goals conceded) until the 1976/77 season, not by goal
 * difference (goals scored − goals conceded). See {@link #goalAverage()}.
 */
public class TeamStanding {

    /** Points awarded for a win under the 1974/75 two-point system. */
    public static final int POINTS_FOR_WIN = 2;

    /** Points awarded for a draw. */
    public static final int POINTS_FOR_DRAW = 1;

    /** Points awarded for a loss. */
    public static final int POINTS_FOR_LOSS = 0;

    private final String teamName;

    private int played;
    private int won;
    private int drawn;
    private int lost;
    private int goalsFor;
    private int goalsAgainst;
    private int points;

    /**
     * Creates a new standing for the given team with all counters at zero.
     *
     * @param teamName the team's name — must not be blank
     * @throws IllegalArgumentException if {@code teamName} is null or blank
     */
    public TeamStanding(String teamName) {
        if (teamName == null || teamName.isBlank()) {
            throw new IllegalArgumentException("Team name must not be blank.");
        }
        this.teamName = teamName.trim();
    }

    /**
     * Records the outcome of one match for this team.
     *
     * <p>Call this method once per match, passing in the goals this team
     * scored and the goals this team conceded. The method determines the
     * result (win/draw/loss) and updates all counters accordingly.
     *
     * <p>Example — team won 3-1:
     * <pre>
     *   standing.update(3, 1);  // goalsFor += 3, goalsAgainst += 1, won++, points += 2
     * </pre>
     *
     * @param goalsScored   goals scored by this team in the match (≥ 0)
     * @param goalsConceded goals conceded by this team in the match (≥ 0)
     * @throws IllegalArgumentException if either argument is negative
     */
    public void update(int goalsScored, int goalsConceded) {
        if (goalsScored < 0) {
            throw new IllegalArgumentException(
                    "Goals scored cannot be negative, got: " + goalsScored);
        }
        if (goalsConceded < 0) {
            throw new IllegalArgumentException(
                    "Goals conceded cannot be negative, got: " + goalsConceded);
        }

        played++;
        goalsFor += goalsScored;
        goalsAgainst += goalsConceded;

        if (goalsScored > goalsConceded) {
            won++;
            points += POINTS_FOR_WIN;
        } else if (goalsScored == goalsConceded) {
            drawn++;
            points += POINTS_FOR_DRAW;
        } else {
            lost++;
            points += POINTS_FOR_LOSS;
        }
    }

    /**
     * Calculates the goal average for ranking purposes.
     *
     * <p>Goal average = goals for ÷ goals against.
     *
     * <p><strong>Zero-goals-against policy:</strong> if a team has conceded
     * zero goals, ordinary division is undefined. This implementation returns
     * {@link Double#POSITIVE_INFINITY}, which sorts <em>above</em> all teams
     * with a finite goal average. This is the fairest interpretation: a team
     * with a perfect defensive record should not be penalised.
     *
     * <p>If both goals for <em>and</em> goals against are zero (e.g. a team
     * has not yet played, or has played only goalless draws), the result is
     * also {@code POSITIVE_INFINITY}. In practice this edge case only appears
     * in test fixtures; real seasons always produce some goals.
     *
     * @return goals-for divided by goals-against, or
     *         {@code Double.POSITIVE_INFINITY} when goals-against is zero
     */
    public double goalAverage() {
        if (goalsAgainst == 0) {
            return Double.POSITIVE_INFINITY;
        }
        return (double) goalsFor / goalsAgainst;
    }

    // -------------------------------------------------------------------------
    // Getters — read-only access; no setters to keep mutation controlled
    // -------------------------------------------------------------------------

    /** @return the team's name */
    public String getTeamName() { return teamName; }

    /** @return total matches played */
    public int getPlayed() { return played; }

    /** @return total matches won */
    public int getWon() { return won; }

    /** @return total matches drawn */
    public int getDrawn() { return drawn; }

    /** @return total matches lost */
    public int getLost() { return lost; }

    /** @return total goals scored across all matches */
    public int getGoalsFor() { return goalsFor; }

    /** @return total goals conceded across all matches */
    public int getGoalsAgainst() { return goalsAgainst; }

    /** @return total points accumulated under the 2-point win system */
    public int getPoints() { return points; }

    /**
     * Returns a human-readable summary of this standing, useful in test
     * failure messages and debug output.
     *
     * <p>Format: {@code TeamName P:x W:x D:x L:x GF:x GA:x Pts:x}
     */
    @Override
    public String toString() {
        return String.format("%s P:%d W:%d D:%d L:%d GF:%d GA:%d Pts:%d",
                teamName, played, won, drawn, lost, goalsFor, goalsAgainst, points);
    }
}

package za.co.football;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Unit tests for {@link MatchResult}.
 *
 * <p>Each test is small and independent. The {@code @DisplayName} annotations
 * describe intent in plain English so the test report is readable without
 * opening the source code.
 *
 * <p>Pattern used throughout: <em>arrange → act → assert</em>.
 * <ul>
 *   <li>Arrange: set up the inputs.</li>
 *   <li>Act: call the code under test.</li>
 *   <li>Assert: verify the outcome.</li>
 * </ul>
 */
@DisplayName("MatchResult")
class MatchResultTest {

    // -------------------------------------------------------------------------
    // Happy path — valid construction
    // -------------------------------------------------------------------------

    @Test
    @DisplayName("stores all four fields when inputs are valid")
    void validMatchIsStoredCorrectly() {
        MatchResult match = new MatchResult("Arsenal", "Chelsea", 2, 1);

        assertEquals("Arsenal", match.homeTeam());
        assertEquals("Chelsea", match.awayTeam());
        assertEquals(2, match.homeGoals());
        assertEquals(1, match.awayGoals());
    }

    @Test
    @DisplayName("a goalless draw is valid")
    void goallessDrawIsValid() {
        MatchResult match = new MatchResult("Leeds United", "Liverpool", 0, 0);

        assertEquals(0, match.homeGoals());
        assertEquals(0, match.awayGoals());
    }

    @Test
    @DisplayName("team names are trimmed of surrounding whitespace")
    void teamNamesAreTrimmed() {
        MatchResult match = new MatchResult("  Ipswich Town  ", " Norwich City ", 1, 0);

        assertEquals("Ipswich Town", match.homeTeam());
        assertEquals("Norwich City", match.awayTeam());
    }

    @Test
    @DisplayName("two MatchResult objects with the same data are equal (record equality)")
    void recordEqualityWorks() {
        MatchResult a = new MatchResult("Arsenal", "Chelsea", 2, 1);
        MatchResult b = new MatchResult("Arsenal", "Chelsea", 2, 1);

        assertEquals(a, b);
    }

    // -------------------------------------------------------------------------
    // Team name validation
    // -------------------------------------------------------------------------

    @Test
    @DisplayName("null home team throws IllegalArgumentException")
    void nullHomeTeamIsRejected() {
        assertThrows(IllegalArgumentException.class,
                () -> new MatchResult(null, "Chelsea", 1, 0));
    }

    @Test
    @DisplayName("null away team throws IllegalArgumentException")
    void nullAwayTeamIsRejected() {
        assertThrows(IllegalArgumentException.class,
                () -> new MatchResult("Arsenal", null, 1, 0));
    }

    @ParameterizedTest(name = "blank home team \"{0}\" is rejected")
    @ValueSource(strings = {"", " ", "   ", "\t"})
    @DisplayName("blank home team throws IllegalArgumentException")
    void blankHomeTeamIsRejected(String blank) {
        assertThrows(IllegalArgumentException.class,
                () -> new MatchResult(blank, "Chelsea", 1, 0));
    }

    @ParameterizedTest(name = "blank away team \"{0}\" is rejected")
    @ValueSource(strings = {"", " ", "   ", "\t"})
    @DisplayName("blank away team throws IllegalArgumentException")
    void blankAwayTeamIsRejected(String blank) {
        assertThrows(IllegalArgumentException.class,
                () -> new MatchResult("Arsenal", blank, 1, 0));
    }

    @Test
    @DisplayName("same team name for home and away throws IllegalArgumentException")
    void sameTeamNameIsRejected() {
        assertThrows(IllegalArgumentException.class,
                () -> new MatchResult("Arsenal", "Arsenal", 1, 1));
    }

    @Test
    @DisplayName("same team name is rejected regardless of case")
    void sameTeamNameCaseInsensitiveIsRejected() {
        assertThrows(IllegalArgumentException.class,
                () -> new MatchResult("arsenal", "ARSENAL", 0, 0));
    }

    @Test
    @DisplayName("same team name is rejected even with surrounding whitespace")
    void sameTeamNameWithWhitespaceIsRejected() {
        assertThrows(IllegalArgumentException.class,
                () -> new MatchResult("Arsenal", "  Arsenal  ", 1, 1));
    }

    // -------------------------------------------------------------------------
    // Goal count validation
    // -------------------------------------------------------------------------

    @Test
    @DisplayName("negative home goals throws IllegalArgumentException")
    void negativeHomeGoalsAreRejected() {
        assertThrows(IllegalArgumentException.class,
                () -> new MatchResult("Arsenal", "Chelsea", -1, 0));
    }

    @Test
    @DisplayName("negative away goals throws IllegalArgumentException")
    void negativeAwayGoalsAreRejected() {
        assertThrows(IllegalArgumentException.class,
                () -> new MatchResult("Arsenal", "Chelsea", 0, -1));
    }
}

package za.co.football;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Unit tests for {@link TeamStanding}.
 *
 * <p>Tests are grouped using {@code @Nested} classes so related scenarios sit
 * together. This keeps the test class navigable as coverage grows.
 *
 * <p>Key things verified here:
 * <ul>
 *   <li>The <strong>2-point win</strong> rule (not 3) — correct for 1974/75.</li>
 *   <li>Goal average = GF ÷ GA, not goal difference.</li>
 *   <li>Goal average when GA = 0 returns {@code POSITIVE_INFINITY}.</li>
 *   <li>Statistics accumulate correctly across several matches.</li>
 * </ul>
 */
@DisplayName("TeamStanding")
class TeamStandingTest {

    // -------------------------------------------------------------------------
    // Construction
    // -------------------------------------------------------------------------

    @Nested
    @DisplayName("construction")
    class Construction {

        @Test
        @DisplayName("new standing starts with all counters at zero")
        void freshStandingIsAllZero() {
            TeamStanding s = new TeamStanding("Arsenal");

            assertEquals("Arsenal", s.getTeamName());
            assertEquals(0, s.getPlayed());
            assertEquals(0, s.getWon());
            assertEquals(0, s.getDrawn());
            assertEquals(0, s.getLost());
            assertEquals(0, s.getGoalsFor());
            assertEquals(0, s.getGoalsAgainst());
            assertEquals(0, s.getPoints());
        }

        @Test
        @DisplayName("team name is trimmed on construction")
        void teamNameIsTrimmed() {
            TeamStanding s = new TeamStanding("  Leeds United  ");
            assertEquals("Leeds United", s.getTeamName());
        }

        @Test
        @DisplayName("null team name throws IllegalArgumentException")
        void nullNameIsRejected() {
            assertThrows(IllegalArgumentException.class, () -> new TeamStanding(null));
        }

        @Test
        @DisplayName("blank team name throws IllegalArgumentException")
        void blankNameIsRejected() {
            assertThrows(IllegalArgumentException.class, () -> new TeamStanding("   "));
        }
    }

    // -------------------------------------------------------------------------
    // Single-match outcomes
    // -------------------------------------------------------------------------

    @Nested
    @DisplayName("single match outcomes")
    class SingleMatchOutcomes {

        private TeamStanding standing;

        @BeforeEach
        void setUp() {
            standing = new TeamStanding("Arsenal");
        }

        @Test
        @DisplayName("win: played+1, won+1, points+2 — verifies 2-point win rule")
        void homeWinAwards2Points() {
            standing.update(3, 1);  // won 3-1

            assertEquals(1, standing.getPlayed());
            assertEquals(1, standing.getWon());
            assertEquals(0, standing.getDrawn());
            assertEquals(0, standing.getLost());
            assertEquals(3, standing.getGoalsFor());
            assertEquals(1, standing.getGoalsAgainst());
            // *** Critical: must be 2, not 3 — this is 1974/75, not modern rules ***
            assertEquals(2, standing.getPoints(),
                    "A win must award 2 points under 1974/75 Football League rules");
        }

        @Test
        @DisplayName("away win: same counters update correctly regardless of perspective")
        void awayWinFromOpponentPerspective() {
            // Suppose Arsenal lost 0-2: they scored 0, conceded 2
            standing.update(0, 2);

            assertEquals(1, standing.getPlayed());
            assertEquals(0, standing.getWon());
            assertEquals(0, standing.getDrawn());
            assertEquals(1, standing.getLost());
            assertEquals(0, standing.getGoalsFor());
            assertEquals(2, standing.getGoalsAgainst());
            assertEquals(0, standing.getPoints());
        }

        @Test
        @DisplayName("draw: played+1, drawn+1, points+1")
        void drawAwards1Point() {
            standing.update(1, 1);

            assertEquals(1, standing.getPlayed());
            assertEquals(0, standing.getWon());
            assertEquals(1, standing.getDrawn());
            assertEquals(0, standing.getLost());
            assertEquals(1, standing.getGoalsFor());
            assertEquals(1, standing.getGoalsAgainst());
            assertEquals(1, standing.getPoints());
        }

        @Test
        @DisplayName("goalless draw: valid and awards 1 point")
        void goallessDrawIsValid() {
            standing.update(0, 0);

            assertEquals(1, standing.getPlayed());
            assertEquals(1, standing.getDrawn());
            assertEquals(1, standing.getPoints());
            assertEquals(0, standing.getGoalsFor());
            assertEquals(0, standing.getGoalsAgainst());
        }

        @Test
        @DisplayName("loss: played+1, lost+1, points unchanged")
        void lossAwards0Points() {
            standing.update(0, 1);

            assertEquals(1, standing.getPlayed());
            assertEquals(0, standing.getWon());
            assertEquals(0, standing.getDrawn());
            assertEquals(1, standing.getLost());
            assertEquals(0, standing.getPoints());
        }

        @Test
        @DisplayName("negative goals scored throws IllegalArgumentException")
        void negativeGoalsScoredIsRejected() {
            assertThrows(IllegalArgumentException.class, () -> standing.update(-1, 0));
        }

        @Test
        @DisplayName("negative goals conceded throws IllegalArgumentException")
        void negativeGoalsConcededIsRejected() {
            assertThrows(IllegalArgumentException.class, () -> standing.update(0, -1));
        }
    }

    // -------------------------------------------------------------------------
    // Accumulated statistics across multiple matches
    // -------------------------------------------------------------------------

    @Nested
    @DisplayName("accumulated statistics across multiple matches")
    class AccumulatedStatistics {

        @Test
        @DisplayName("ten matches accumulate played, goals and points correctly")
        void tenMatchesAccumulateCorrectly() {
            TeamStanding s = new TeamStanding("Ipswich Town");

            // Simulate a 10-match sequence: W W W W W W W D L L
            s.update(2, 0);  // win
            s.update(3, 1);  // win
            s.update(1, 0);  // win
            s.update(2, 1);  // win
            s.update(4, 2);  // win
            s.update(1, 0);  // win
            s.update(3, 2);  // win
            s.update(1, 1);  // draw
            s.update(0, 2);  // loss
            s.update(1, 3);  // loss

            assertEquals(10, s.getPlayed());
            assertEquals(7,  s.getWon());
            assertEquals(1,  s.getDrawn());
            assertEquals(2,  s.getLost());

            // Goals: scored 2+3+1+2+4+1+3+1+0+1 = 18
            assertEquals(18, s.getGoalsFor());
            // Goals against: 0+1+0+1+2+0+2+1+2+3 = 12
            assertEquals(12, s.getGoalsAgainst());

            // Points: 7 wins × 2 + 1 draw × 1 + 2 losses × 0 = 15
            assertEquals(15, s.getPoints());
        }

        @Test
        @DisplayName("won + drawn + lost always equals played")
        void wdlSumEqualsPlayed() {
            TeamStanding s = new TeamStanding("Chelsea");
            s.update(2, 1);
            s.update(0, 0);
            s.update(1, 2);
            s.update(3, 0);

            assertEquals(s.getPlayed(), s.getWon() + s.getDrawn() + s.getLost());
        }

        @Test
        @DisplayName("points never exceed played × 2 under 2-point win system")
        void pointsNeverExceedTwicePlayedUnder2PointSystem() {
            TeamStanding s = new TeamStanding("Liverpool");
            s.update(5, 0);  // win
            s.update(4, 0);  // win
            s.update(3, 0);  // win

            assertTrue(s.getPoints() <= s.getPlayed() * TeamStanding.POINTS_FOR_WIN,
                    "Maximum possible points = played × 2 under the 1974/75 system");
            assertEquals(6, s.getPoints());
        }
    }

    // -------------------------------------------------------------------------
    // Goal average
    // -------------------------------------------------------------------------

    @Nested
    @DisplayName("goal average")
    class GoalAverageTests {

        @Test
        @DisplayName("goal average = goals for / goals against")
        void goalAverageIsCorrect() {
            TeamStanding s = new TeamStanding("Arsenal");
            s.update(3, 2); // GF=3, GA=2 → average = 1.5

            assertEquals(1.5, s.goalAverage(), 1e-9,
                    "Goal average must be GF ÷ GA, not goal difference");
        }

        @Test
        @DisplayName("goal average is not goal difference")
        void goalAverageIsNotGoalDifference() {
            TeamStanding s = new TeamStanding("Arsenal");
            s.update(4, 2); // GF=4, GA=2

            double average    = s.goalAverage();       // expected: 2.0
            double difference = s.getGoalsFor() - s.getGoalsAgainst(); // would be: 2.0 here too

            // Use a case where the two formulas diverge: GF=6, GA=3
            TeamStanding s2 = new TeamStanding("Chelsea");
            s2.update(6, 3); // average=2.0, difference=3.0 — different values

            assertNotEquals(s2.getGoalsFor() - s2.getGoalsAgainst(),
                            s2.goalAverage(),
                            "This confirms the two formulas produce different results; " +
                            "we use goal average, not difference");
        }

        @Test
        @DisplayName("goal average with GA = 0 returns POSITIVE_INFINITY")
        void goalAverageWithZeroGoalsAgainstIsPositiveInfinity() {
            TeamStanding s = new TeamStanding("Stoke City");
            s.update(1, 0); // scored 1, conceded 0 → GA = 0

            assertEquals(Double.POSITIVE_INFINITY, s.goalAverage(),
                    "A team with GA=0 gets POSITIVE_INFINITY so it ranks above " +
                    "all teams with a finite goal average");
        }

        @Test
        @DisplayName("goal average with GF = 0 and GA = 0 returns POSITIVE_INFINITY")
        void goalAverageWithBothZeroIsPositiveInfinity() {
            TeamStanding s = new TeamStanding("Stoke City");
            s.update(0, 0); // goalless draw — GF=0, GA=0

            assertEquals(Double.POSITIVE_INFINITY, s.goalAverage(),
                    "0/0 is undefined; returning POSITIVE_INFINITY avoids NaN " +
                    "and is consistent with the GA=0 policy");
        }

        @Test
        @DisplayName("goal average with GF = 0 and GA > 0 is zero")
        void goalAverageWithZeroGoalsScoredIsZero() {
            TeamStanding s = new TeamStanding("Coventry City");
            s.update(0, 3); // lost 0-3 → GF=0, GA=3

            assertEquals(0.0, s.goalAverage(), 1e-9);
        }

        @Test
        @DisplayName("goal average accumulates over multiple matches")
        void goalAverageAccumulatesOverMultipleMatches() {
            TeamStanding s = new TeamStanding("Derby County");
            s.update(2, 1); // GF=2, GA=1
            s.update(4, 3); // GF=6, GA=4

            // goalAverage = 6/4 = 1.5
            assertEquals(1.5, s.goalAverage(), 1e-9);
        }
    }

    // -------------------------------------------------------------------------
    // toString
    // -------------------------------------------------------------------------

    @Test
    @DisplayName("toString includes team name and key statistics")
    void toStringContainsUsefulInfo() {
        TeamStanding s = new TeamStanding("Arsenal");
        s.update(2, 1);

        String str = s.toString();
        assertTrue(str.contains("Arsenal"),  "toString should contain team name");
        assertTrue(str.contains("2"),        "toString should contain goals for");
        assertTrue(str.contains("1"),        "toString should contain goals against");
    }
}

