package za.co.football;

/**
 * Thrown when a CSV file does not conform to the expected format.
 *
 * <p>Every instance carries the 1-based line number at which the problem was
 * detected, making it straightforward to report useful error messages to the
 * user without needing a stack trace.
 *
 * <p>This is an unchecked exception (extends {@link RuntimeException}) so that
 * callers are not forced to wrap every read call in a try-catch. Code that
 * needs to distinguish a parse error from an I/O error can catch it explicitly.
 *
 * <p>Example message: {@code "Line 4: expected 4 columns but found 3"}
 */
public class CsvParseException extends RuntimeException {

    private final int lineNumber;

    /**
     * Constructs a new {@code CsvParseException} with a description and the
     * line number at which the error occurred.
     *
     * @param lineNumber 1-based line number in the source CSV file
     * @param message    human-readable description of the problem
     */
    public CsvParseException(int lineNumber, String message) {
        super("Line " + lineNumber + ": " + message);
        this.lineNumber = lineNumber;
    }

    /**
     * Constructs a {@code CsvParseException} wrapping an underlying cause.
     *
     * @param lineNumber 1-based line number in the source CSV file
     * @param message    human-readable description of the problem
     * @param cause      the underlying exception (e.g. {@link NumberFormatException})
     */
    public CsvParseException(int lineNumber, String message, Throwable cause) {
        super("Line " + lineNumber + ": " + message, cause);
        this.lineNumber = lineNumber;
    }

    /**
     * @return the 1-based line number in the source CSV file where the error
     *         was detected
     */
    public int getLineNumber() {
        return lineNumber;
    }
}

package za.co.football;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

/**
 * Reads football match results from a UTF-8 CSV file and returns them as a
 * list of {@link MatchResult} objects.
 *
 * <h2>Expected file format</h2>
 * <pre>
 *   home_team,away_team,home_goals,away_goals
 *   Arsenal,Chelsea,2,1
 *   Leeds United,Liverpool,0,0
 *   "Notts County","Stoke City",1,2
 * </pre>
 *
 * <h2>Parsing rules</h2>
 * <ul>
 *   <li><strong>Header:</strong> the first non-blank line must be exactly
 *       {@code home_team,away_team,home_goals,away_goals} (case-insensitive,
 *       whitespace trimmed). A missing or wrong header raises
 *       {@link CsvParseException}.</li>
 *   <li><strong>Blank lines:</strong> silently skipped anywhere in the file.</li>
 *   <li><strong>Whitespace:</strong> each parsed field is trimmed before use.</li>
 *   <li><strong>Column count:</strong> exactly four columns are required per
 *       data row. Rows with more or fewer columns raise {@link CsvParseException}
 *       with the 1-based line number.</li>
 *   <li><strong>Goals:</strong> must be non-negative integers. Non-numeric or
 *       negative values raise {@link CsvParseException}.</li>
 *   <li><strong>Quoted fields (RFC 4180 subset):</strong> a field may be
 *       surrounded by {@code "..."} to allow commas inside team names.
 *       A literal double-quote inside a quoted field is written as {@code ""}.
 *       Example: {@code "O'Neill, Frank's XI"} or {@code "He said ""hello"""}.
 *       <em>Limitation:</em> embedded newlines inside quoted fields are not
 *       supported. Each logical CSV record must fit on a single line.</li>
 *   <li><strong>Encoding:</strong> UTF-8.</li>
 * </ul>
 *
 * <h2>No third-party CSV library</h2>
 * Parsing is hand-rolled to avoid adding dependencies for a well-scoped problem.
 * The only unsupported RFC 4180 feature is multi-line quoted fields, which
 * cannot occur in football team names.
 *
 * <h2>Usage</h2>
 * <pre>
 *   List&lt;MatchResult&gt; results = CsvMatchReader.read(Path.of("results.csv"));
 * </pre>
 */
public final class CsvMatchReader {

    /** Expected header — normalised to lower-case for comparison. */
    private static final String EXPECTED_HEADER = "home_team,away_team,home_goals,away_goals";

    private CsvMatchReader() {}

    /**
     * Reads all match results from the given CSV file.
     *
     * @param csvFile path to the CSV file; must exist and be readable
     * @return an unmodifiable list of {@link MatchResult} objects in file order;
     *         empty list if the file contains only a header (or only blank lines)
     * @throws UncheckedIOException if the file cannot be read
     * @throws CsvParseException    if any line does not conform to the expected format
     * @throws IllegalArgumentException if {@code csvFile} is null
     */
    public static List<MatchResult> read(Path csvFile) {
        if (csvFile == null) {
            throw new IllegalArgumentException("csvFile must not be null.");
        }

        List<MatchResult> results = new ArrayList<>();

        try (BufferedReader reader = Files.newBufferedReader(csvFile, StandardCharsets.UTF_8)) {
            String rawLine;
            int lineNumber = 0;
            boolean headerSeen = false;

            while ((rawLine = reader.readLine()) != null) {
                lineNumber++;

                // Skip blank lines silently.
                if (rawLine.isBlank()) {
                    continue;
                }

                if (!headerSeen) {
                    // Validate the header.
                    String normalisedHeader = rawLine.trim().toLowerCase();
                    if (!normalisedHeader.equals(EXPECTED_HEADER)) {
                        throw new CsvParseException(lineNumber,
                                "invalid header. Expected \"" + EXPECTED_HEADER +
                                "\" but found \"" + rawLine.trim() + "\".");
                    }
                    headerSeen = true;
                    continue;
                }

                // Parse a data row.
                List<String> fields = parseCsvLine(rawLine, lineNumber);

                if (fields.size() != 4) {
                    throw new CsvParseException(lineNumber,
                            "expected 4 columns but found " + fields.size() + ".");
                }

                String homeTeam  = fields.get(0).trim();
                String awayTeam  = fields.get(1).trim();
                String homeGoalRaw = fields.get(2).trim();
                String awayGoalRaw = fields.get(3).trim();

                int homeGoals = parseGoals(homeGoalRaw, "home_goals", lineNumber);
                int awayGoals = parseGoals(awayGoalRaw, "away_goals", lineNumber);

                // MatchResult's own constructor validates team names and goals.
                // We let its IllegalArgumentException propagate as-is; the caller
                // will see a clear message (e.g. "A team cannot play against itself").
                try {
                    results.add(new MatchResult(homeTeam, awayTeam, homeGoals, awayGoals));
                } catch (IllegalArgumentException e) {
                    throw new CsvParseException(lineNumber, e.getMessage(), e);
                }
            }

            if (!headerSeen) {
                // File was entirely blank — treat it as having no header.
                // An empty file is allowed to return an empty list, but a file
                // with no recognisable header at all is an error.
                // If lineNumber == 0 the file was truly empty; that's fine.
                if (lineNumber > 0) {
                    throw new CsvParseException(lineNumber,
                            "file contains no valid header row.");
                }
            }

        } catch (IOException e) {
            throw new UncheckedIOException("Failed to read CSV file: " + csvFile, e);
        }

        return List.copyOf(results);  // unmodifiable snapshot
    }

    // -------------------------------------------------------------------------
    // Private helpers
    // -------------------------------------------------------------------------

    /**
     * Parses one CSV line into a list of field strings, respecting RFC 4180
     * double-quote rules.
     *
     * <p>A field is either:
     * <ul>
     *   <li>Unquoted: characters up to the next comma or end of line.</li>
     *   <li>Quoted: starts with {@code "}, ends with a closing {@code "} that
     *       is not doubled. A {@code ""} inside a quoted field becomes a single
     *       {@code "} in the result.</li>
     * </ul>
     *
     * @param line       the raw line to parse
     * @param lineNumber 1-based line number, for error messages
     * @return list of parsed field values (not yet trimmed)
     * @throws CsvParseException if quoting is malformed
     */
    static List<String> parseCsvLine(String line, int lineNumber) {
        List<String> fields = new ArrayList<>();
        StringBuilder current = new StringBuilder();
        int i = 0;
        int len = line.length();

        while (i < len) {
            char ch = line.charAt(i);

            if (ch == '"') {
                // Quoted field: consume until closing quote, handling "" escapes.
                i++; // skip opening quote
                while (i < len) {
                    char inner = line.charAt(i);
                    if (inner == '"') {
                        // Could be end of field or an escaped quote ("").
                        if (i + 1 < len && line.charAt(i + 1) == '"') {
                            current.append('"'); // escaped quote
                            i += 2;
                        } else {
                            i++; // closing quote — end of quoted field
                            break;
                        }
                    } else {
                        current.append(inner);
                        i++;
                    }
                }
                // After the closing quote, the next character must be a comma or EOL.
                if (i < len && line.charAt(i) != ',') {
                    throw new CsvParseException(lineNumber,
                            "unexpected character after closing quote at position " + i + ".");
                }
            } else if (ch == ',') {
                // Field separator — commit current field, start fresh.
                fields.add(current.toString());
                current.setLength(0);
                i++;
                // If the line ends with a comma, that's a trailing empty field.
                if (i == len) {
                    fields.add("");
                }
                continue;
            } else {
                current.append(ch);
                i++;
            }
        }

        // Commit the last field (even if empty for a line that is just ",,,").
        fields.add(current.toString());
        return fields;
    }

    /**
     * Parses a goal count string into a non-negative integer.
     *
     * @param raw        the raw string from the CSV field
     * @param fieldName  column name, for error messages
     * @param lineNumber 1-based line number, for error messages
     * @return the parsed goal count
     * @throws CsvParseException if the value is not a non-negative integer
     */
    private static int parseGoals(String raw, String fieldName, int lineNumber) {
        int value;
        try {
            value = Integer.parseInt(raw);
        } catch (NumberFormatException e) {
            throw new CsvParseException(lineNumber,
                    fieldName + " is not a valid integer: \"" + raw + "\".", e);
        }
        if (value < 0) {
            throw new CsvParseException(lineNumber,
                    fieldName + " cannot be negative: " + value + ".");
        }
        return value;
    }
}

package za.co.football;

import java.io.BufferedWriter;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

/**
 * Writes a ranked list of {@link TeamStanding} objects to a UTF-8 CSV file.
 *
 * <h2>Output columns</h2>
 * <pre>
 *   position,team,played,won,drawn,lost,goals_for,goals_against,goal_average,points
 * </pre>
 *
 * <h2>Column details</h2>
 * <ul>
 *   <li><strong>position:</strong> 1-based rank (1 = top of the table).</li>
 *   <li><strong>team:</strong> team name, RFC 4180-escaped if necessary (see below).</li>
 *   <li><strong>played / won / drawn / lost:</strong> integer match counts.</li>
 *   <li><strong>goals_for / goals_against:</strong> integer goal counts.</li>
 *   <li><strong>goal_average:</strong> goals_for ÷ goals_against, formatted to
 *       three decimal places.
 *       <em>Special case:</em> when goals_against is zero,
 *       {@link TeamStanding#goalAverage()} returns {@link Double#POSITIVE_INFINITY}.
 *       This column is written as an <strong>empty field</strong> (nothing between
 *       the two commas) rather than the string {@code "Infinity"} or any invented
 *       large number. This is the most spreadsheet-compatible representation of an
 *       undefined ratio. The README documents this convention.</li>
 *   <li><strong>points:</strong> integer total.</li>
 * </ul>
 *
 * <h2>Team name escaping (RFC 4180)</h2>
 * If a team name contains a comma, a double-quote character, or a newline, it
 * is wrapped in double-quotes and any embedded double-quotes are doubled.
 * Examples:
 * <pre>
 *   Arsenal           →  Arsenal
 *   Notts, County     →  "Notts, County"
 *   Say "hello" FC    →  "Say ""hello"" FC"
 * </pre>
 *
 * <h2>Usage</h2>
 * <pre>
 *   List&lt;TeamStanding&gt; standings = StandingsCalculator.calculate(results);
 *   CsvStandingsWriter.write(standings, Path.of("output/standings.csv"));
 * </pre>
 */
public final class CsvStandingsWriter {

    /** CSV header row — column order is part of the public contract. */
    static final String HEADER =
            "position,team,played,won,drawn,lost,goals_for,goals_against,goal_average,points";

    private CsvStandingsWriter() {}

    /**
     * Writes the standings to the given path, creating or overwriting the file.
     *
     * <p>Parent directories must already exist; this method does not create them.
     *
     * @param standings ranked list of standings (index 0 = position 1);
     *                  must not be null; individual entries must not be null
     * @param outputFile path of the CSV file to write
     * @throws IllegalArgumentException if {@code standings} or {@code outputFile} is null
     * @throws UncheckedIOException if the file cannot be written
     */
    public static void write(List<TeamStanding> standings, Path outputFile) {
        if (standings == null) {
            throw new IllegalArgumentException("standings must not be null.");
        }
        if (outputFile == null) {
            throw new IllegalArgumentException("outputFile must not be null.");
        }

        try (BufferedWriter writer = Files.newBufferedWriter(outputFile, StandardCharsets.UTF_8)) {
            writer.write(HEADER);
            writer.newLine();

            for (int i = 0; i < standings.size(); i++) {
                TeamStanding s = standings.get(i);
                if (s == null) {
                    throw new IllegalArgumentException(
                            "standings list contains a null entry at index " + i + ".");
                }
                writer.write(formatRow(i + 1, s));
                writer.newLine();
            }
        } catch (IOException e) {
            throw new UncheckedIOException("Failed to write CSV file: " + outputFile, e);
        }
    }

    // -------------------------------------------------------------------------
    // Private helpers
    // -------------------------------------------------------------------------

    /**
     * Formats one standings row as a CSV string.
     *
     * @param position 1-based rank
     * @param s        the team's standing
     * @return the formatted CSV row (no trailing newline)
     */
    static String formatRow(int position, TeamStanding s) {
        return position
                + "," + escapeCsvField(s.getTeamName())
                + "," + s.getPlayed()
                + "," + s.getWon()
                + "," + s.getDrawn()
                + "," + s.getLost()
                + "," + s.getGoalsFor()
                + "," + s.getGoalsAgainst()
                + "," + formatGoalAverage(s.goalAverage())
                + "," + s.getPoints();
    }

    /**
     * Formats the goal average for CSV output.
     *
     * <ul>
     *   <li>Normal values → three decimal places (e.g. {@code 2.333}).</li>
     *   <li>{@link Double#POSITIVE_INFINITY} (GA = 0) → empty string.
     *       Writing {@code "Infinity"} would be confusing and non-numeric for
     *       spreadsheet tools. An empty field clearly signals that the value is
     *       undefined and documents the GA=0 edge case visually.</li>
     * </ul>
     *
     * @param goalAverage the value from {@link TeamStanding#goalAverage()}
     * @return formatted string, never null
     */
    static String formatGoalAverage(double goalAverage) {
        if (Double.isInfinite(goalAverage)) {
            return "";  // GA = 0: undefined ratio — empty field in CSV
        }
        return String.format("%.3f", goalAverage);
    }

    /**
     * Escapes a field value for RFC 4180-compliant CSV output.
     *
     * <p>If the value contains a comma, double-quote, or newline character, it
     * is wrapped in double-quotes and any embedded double-quotes are doubled.
     * Values that require no escaping are returned unchanged.
     *
     * @param value the field value to escape (must not be null)
     * @return the escaped field, ready to embed in a CSV row
     */
    static String escapeCsvField(String value) {
        // Check whether quoting is necessary.
        boolean needsQuoting = value.contains(",")
                || value.contains("\"")
                || value.contains("\n")
                || value.contains("\r");

        if (!needsQuoting) {
            return value;
        }

        // Wrap in quotes and double any embedded quotes.
        return "\"" + value.replace("\"", "\"\"") + "\"";
    }
}

package za.co.football;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Unit tests for {@link CsvMatchReader}.
 *
 * <p>All file I/O uses {@code @TempDir} — JUnit 5 creates a temporary directory
 * before each test class and deletes it (and everything inside it) afterwards.
 * No temporary files are left on disk after the test run.
 *
 * <p>Each test writes a small CSV string to a temp file and calls
 * {@link CsvMatchReader#read(Path)}, then asserts the result or the exception.
 */
@DisplayName("CsvMatchReader")
class CsvMatchReaderTest {

    @TempDir
    Path tempDir;

    // -------------------------------------------------------------------------
    // Helper: write a string to a temp file and return its Path
    // -------------------------------------------------------------------------

    private Path writeCsv(String content) throws Exception {
        Path file = tempDir.resolve("test.csv");
        Files.writeString(file, content, StandardCharsets.UTF_8);
        return file;
    }

    // -------------------------------------------------------------------------
    // Happy path
    // -------------------------------------------------------------------------

    @Nested
    @DisplayName("valid input")
    class ValidInput {

        @Test
        @DisplayName("reads a file with one data row")
        void readsOneRow() throws Exception {
            Path csv = writeCsv(
                    "home_team,away_team,home_goals,away_goals\n" +
                    "Arsenal,Chelsea,2,1\n");

            List<MatchResult> results = CsvMatchReader.read(csv);

            assertEquals(1, results.size());
            MatchResult m = results.get(0);
            assertEquals("Arsenal", m.homeTeam());
            assertEquals("Chelsea", m.awayTeam());
            assertEquals(2, m.homeGoals());
            assertEquals(1, m.awayGoals());
        }

        @Test
        @DisplayName("reads multiple data rows in order")
        void readsMultipleRows() throws Exception {
            Path csv = writeCsv(
                    "home_team,away_team,home_goals,away_goals\n" +
                    "Arsenal,Chelsea,2,1\n" +
                    "Leeds United,Liverpool,0,0\n" +
                    "Ipswich Town,Stoke City,3,2\n");

            List<MatchResult> results = CsvMatchReader.read(csv);

            assertEquals(3, results.size());
            assertEquals("Arsenal",      results.get(0).homeTeam());
            assertEquals("Leeds United", results.get(1).homeTeam());
            assertEquals("Ipswich Town", results.get(2).homeTeam());
        }

        @Test
        @DisplayName("header is case-insensitive")
        void headerIsCaseInsensitive() throws Exception {
            Path csv = writeCsv(
                    "HOME_TEAM,AWAY_TEAM,HOME_GOALS,AWAY_GOALS\n" +
                    "Arsenal,Chelsea,1,0\n");

            assertDoesNotThrow(() -> CsvMatchReader.read(csv));
        }

        @Test
        @DisplayName("blank lines anywhere are silently skipped")
        void blankLinesSkipped() throws Exception {
            Path csv = writeCsv(
                    "\n" +
                    "home_team,away_team,home_goals,away_goals\n" +
                    "\n" +
                    "Arsenal,Chelsea,2,1\n" +
                    "\n");

            List<MatchResult> results = CsvMatchReader.read(csv);
            assertEquals(1, results.size());
        }

        @Test
        @DisplayName("field whitespace is trimmed")
        void fieldWhitespaceIsTrimmed() throws Exception {
            Path csv = writeCsv(
                    "home_team,away_team,home_goals,away_goals\n" +
                    "  Arsenal  ,  Chelsea  , 2 , 1 \n");

            List<MatchResult> results = CsvMatchReader.read(csv);
            assertEquals("Arsenal", results.get(0).homeTeam());
            assertEquals("Chelsea", results.get(0).awayTeam());
        }

        @Test
        @DisplayName("returns an empty list when file contains only the header")
        void headerOnlyFileReturnsEmptyList() throws Exception {
            Path csv = writeCsv("home_team,away_team,home_goals,away_goals\n");
            List<MatchResult> results = CsvMatchReader.read(csv);
            assertTrue(results.isEmpty());
        }

        @Test
        @DisplayName("truly empty file returns an empty list")
        void emptyFileReturnsEmptyList() throws Exception {
            Path csv = writeCsv("");
            List<MatchResult> results = CsvMatchReader.read(csv);
            assertTrue(results.isEmpty());
        }

        @Test
        @DisplayName("goalless draw (0-0) is valid")
        void goallessDrawIsValid() throws Exception {
            Path csv = writeCsv(
                    "home_team,away_team,home_goals,away_goals\n" +
                    "Arsenal,Chelsea,0,0\n");

            List<MatchResult> results = CsvMatchReader.read(csv);
            assertEquals(0, results.get(0).homeGoals());
            assertEquals(0, results.get(0).awayGoals());
        }

        @Test
        @DisplayName("returned list is unmodifiable")
        void returnedListIsUnmodifiable() throws Exception {
            Path csv = writeCsv(
                    "home_team,away_team,home_goals,away_goals\n" +
                    "Arsenal,Chelsea,1,0\n");

            List<MatchResult> results = CsvMatchReader.read(csv);
            assertThrows(UnsupportedOperationException.class,
                    () -> results.add(new MatchResult("X", "Y", 0, 0)));
        }
    }

    // -------------------------------------------------------------------------
    // Quoted fields
    // -------------------------------------------------------------------------

    @Nested
    @DisplayName("quoted fields (RFC 4180)")
    class QuotedFields {

        @Test
        @DisplayName("quoted team name containing a comma is parsed correctly")
        void quotedNameWithComma() throws Exception {
            Path csv = writeCsv(
                    "home_team,away_team,home_goals,away_goals\n" +
                    "\"Notts, County\",Chelsea,1,0\n");

            List<MatchResult> results = CsvMatchReader.read(csv);
            assertEquals("Notts, County", results.get(0).homeTeam());
        }

        @Test
        @DisplayName("escaped double-quote inside a quoted field becomes a single quote")
        void escapedQuoteInsideQuotedField() throws Exception {
            Path csv = writeCsv(
                    "home_team,away_team,home_goals,away_goals\n" +
                    "\"Say \"\"hello\"\" FC\",Chelsea,1,0\n");

            List<MatchResult> results = CsvMatchReader.read(csv);
            assertEquals("Say \"hello\" FC", results.get(0).homeTeam());
        }

        @Test
        @DisplayName("unquoted field still works when others are quoted")
        void mixedQuotedAndUnquotedFields() throws Exception {
            Path csv = writeCsv(
                    "home_team,away_team,home_goals,away_goals\n" +
                    "Arsenal,\"Leeds United\",2,0\n");

            List<MatchResult> results = CsvMatchReader.read(csv);
            assertEquals("Arsenal",      results.get(0).homeTeam());
            assertEquals("Leeds United", results.get(0).awayTeam());
        }
    }

    // -------------------------------------------------------------------------
    // parseCsvLine unit tests (package-private method tested directly)
    // -------------------------------------------------------------------------

    @Nested
    @DisplayName("parseCsvLine (internal parser)")
    class ParseCsvLine {

        @Test
        @DisplayName("simple unquoted row splits on commas")
        void simpleUnquotedRow() {
            List<String> fields = CsvMatchReader.parseCsvLine("a,b,c,d", 1);
            assertEquals(List.of("a", "b", "c", "d"), fields);
        }

        @Test
        @DisplayName("quoted field with comma is kept as one field")
        void quotedFieldWithComma() {
            List<String> fields = CsvMatchReader.parseCsvLine("\"a,b\",c", 1);
            assertEquals(List.of("a,b", "c"), fields);
        }

        @Test
        @DisplayName("escaped double-quote inside quoted field")
        void escapedDoubleQuote() {
            List<String> fields = CsvMatchReader.parseCsvLine("\"a\"\"b\",c", 1);
            assertEquals(List.of("a\"b", "c"), fields);
        }

        @Test
        @DisplayName("empty field between commas")
        void emptyFieldBetweenCommas() {
            List<String> fields = CsvMatchReader.parseCsvLine("a,,c", 1);
            assertEquals(List.of("a", "", "c"), fields);
        }

        @Test
        @DisplayName("character after closing quote that is not comma throws")
        void charAfterClosingQuoteThrows() {
            assertThrows(CsvParseException.class,
                    () -> CsvMatchReader.parseCsvLine("\"a\"X,b", 1));
        }
    }

    // -------------------------------------------------------------------------
    // Error cases
    // -------------------------------------------------------------------------

    @Nested
    @DisplayName("error cases")
    class ErrorCases {

        @Test
        @DisplayName("null path throws IllegalArgumentException")
        void nullPathThrows() {
            assertThrows(IllegalArgumentException.class,
                    () -> CsvMatchReader.read(null));
        }

        @Test
        @DisplayName("missing header throws CsvParseException")
        void missingHeaderThrows() throws Exception {
            Path csv = writeCsv("Arsenal,Chelsea,2,1\n");
            CsvParseException ex = assertThrows(CsvParseException.class,
                    () -> CsvMatchReader.read(csv));
            assertEquals(1, ex.getLineNumber());
        }

        @Test
        @DisplayName("wrong header text throws CsvParseException")
        void wrongHeaderThrows() throws Exception {
            Path csv = writeCsv("team1,team2,score1,score2\nArsenal,Chelsea,2,1\n");
            CsvParseException ex = assertThrows(CsvParseException.class,
                    () -> CsvMatchReader.read(csv));
            assertEquals(1, ex.getLineNumber());
        }

        @Test
        @DisplayName("row with too few columns throws CsvParseException with correct line number")
        void tooFewColumnsThrows() throws Exception {
            Path csv = writeCsv(
                    "home_team,away_team,home_goals,away_goals\n" +
                    "Arsenal,Chelsea,2\n");   // only 3 columns

            CsvParseException ex = assertThrows(CsvParseException.class,
                    () -> CsvMatchReader.read(csv));
            assertEquals(2, ex.getLineNumber(),
                    "Error should be reported on line 2 (the bad data row)");
        }

        @Test
        @DisplayName("row with too many columns throws CsvParseException")
        void tooManyColumnsThrows() throws Exception {
            Path csv = writeCsv(
                    "home_team,away_team,home_goals,away_goals\n" +
                    "Arsenal,Chelsea,2,1,extra\n");  // 5 columns

            CsvParseException ex = assertThrows(CsvParseException.class,
                    () -> CsvMatchReader.read(csv));
            assertEquals(2, ex.getLineNumber());
        }

        @Test
        @DisplayName("non-numeric home_goals throws CsvParseException")
        void nonNumericHomeGoalsThrows() throws Exception {
            Path csv = writeCsv(
                    "home_team,away_team,home_goals,away_goals\n" +
                    "Arsenal,Chelsea,two,1\n");

            CsvParseException ex = assertThrows(CsvParseException.class,
                    () -> CsvMatchReader.read(csv));
            assertEquals(2, ex.getLineNumber());
            assertTrue(ex.getMessage().contains("home_goals"));
        }

        @Test
        @DisplayName("non-numeric away_goals throws CsvParseException")
        void nonNumericAwayGoalsThrows() throws Exception {
            Path csv = writeCsv(
                    "home_team,away_team,home_goals,away_goals\n" +
                    "Arsenal,Chelsea,1,one\n");

            CsvParseException ex = assertThrows(CsvParseException.class,
                    () -> CsvMatchReader.read(csv));
            assertEquals(2, ex.getLineNumber());
            assertTrue(ex.getMessage().contains("away_goals"));
        }

        @Test
        @DisplayName("negative home_goals throws CsvParseException")
        void negativeHomeGoalsThrows() throws Exception {
            Path csv = writeCsv(
                    "home_team,away_team,home_goals,away_goals\n" +
                    "Arsenal,Chelsea,-1,0\n");

            assertThrows(CsvParseException.class, () -> CsvMatchReader.read(csv));
        }

        @Test
        @DisplayName("negative away_goals throws CsvParseException")
        void negativeAwayGoalsThrows() throws Exception {
            Path csv = writeCsv(
                    "home_team,away_team,home_goals,away_goals\n" +
                    "Arsenal,Chelsea,0,-1\n");

            assertThrows(CsvParseException.class, () -> CsvMatchReader.read(csv));
        }

        @Test
        @DisplayName("same team as home and away throws CsvParseException")
        void sameTeamThrows() throws Exception {
            Path csv = writeCsv(
                    "home_team,away_team,home_goals,away_goals\n" +
                    "Arsenal,Arsenal,1,1\n");

            CsvParseException ex = assertThrows(CsvParseException.class,
                    () -> CsvMatchReader.read(csv));
            assertEquals(2, ex.getLineNumber());
        }

        @Test
        @DisplayName("error on line 4 while lines 2 and 3 are valid")
        void errorLineNumberIsAccurate() throws Exception {
            Path csv = writeCsv(
                    "home_team,away_team,home_goals,away_goals\n" +
                    "Arsenal,Chelsea,2,1\n" +
                    "Leeds United,Liverpool,0,0\n" +
                    "Ipswich Town,Stoke City,bad,2\n");

            CsvParseException ex = assertThrows(CsvParseException.class,
                    () -> CsvMatchReader.read(csv));
            assertEquals(4, ex.getLineNumber());
        }
    }
}

package za.co.football;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Unit tests for {@link CsvStandingsWriter}.
 *
 * <p>Tests that need a file use {@code @TempDir} — JUnit 5 creates and cleans
 * up the directory automatically. Most structural tests call the package-private
 * static helpers ({@code formatRow}, {@code formatGoalAverage},
 * {@code escapeCsvField}) directly to stay fast and independent of file I/O.
 */
@DisplayName("CsvStandingsWriter")
class CsvStandingsWriterTest {

    @TempDir
    Path tempDir;

    // -------------------------------------------------------------------------
    // Helper: build a frozen TeamStanding with known stats
    // -------------------------------------------------------------------------

    /**
     * Builds a {@code TeamStanding} by feeding it a series of match updates,
     * then freezes it by passing it through {@link StandingsCalculator}.
     * Returns the first standing in the result (position 1).
     *
     * <p>We use the calculator to get a properly frozen standing, because
     * {@code CsvStandingsWriter} is expected to receive frozen standings in
     * normal use.
     */
    private static TeamStanding standingFor(String team, int goalsFor, int goalsAgainst) {
        // Construct a single match that gives the team the desired stats.
        // Team wins (or we don't care about the result for writer tests).
        List<MatchResult> matches = List.of(
                new MatchResult(team, "Opponent", goalsFor, goalsAgainst));
        return StandingsCalculator.calculate(matches).stream()
                .filter(s -> s.getTeamName().equals(team))
                .findFirst()
                .orElseThrow();
    }

    // -------------------------------------------------------------------------
    // formatGoalAverage (unit tests for the static helper)
    // -------------------------------------------------------------------------

    @Nested
    @DisplayName("formatGoalAverage")
    class FormatGoalAverage {

        @Test
        @DisplayName("normal value formatted to 3 decimal places")
        void normalValueFormattedToThreeDecimalPlaces() {
            assertEquals("2.000", CsvStandingsWriter.formatGoalAverage(2.0));
            assertEquals("1.500", CsvStandingsWriter.formatGoalAverage(1.5));
            assertEquals("0.333", CsvStandingsWriter.formatGoalAverage(1.0 / 3.0));
        }

        @Test
        @DisplayName("POSITIVE_INFINITY (GA=0) writes as empty string")
        void positiveInfinityWritesAsEmptyString() {
            assertEquals("", CsvStandingsWriter.formatGoalAverage(Double.POSITIVE_INFINITY),
                    "Goal average must be empty string when GA=0, not \"Infinity\"");
        }

        @Test
        @DisplayName("zero goal average (GF=0, GA>0) writes as 0.000")
        void zeroGoalAverageWritesAsZero() {
            assertEquals("0.000", CsvStandingsWriter.formatGoalAverage(0.0));
        }
    }

    // -------------------------------------------------------------------------
    // escapeCsvField (unit tests for the static helper)
    // -------------------------------------------------------------------------

    @Nested
    @DisplayName("escapeCsvField")
    class EscapeCsvField {

        @Test
        @DisplayName("plain name needs no escaping")
        void plainNameUnchanged() {
            assertEquals("Arsenal", CsvStandingsWriter.escapeCsvField("Arsenal"));
        }

        @Test
        @DisplayName("name with comma is wrapped in quotes")
        void nameWithCommaIsQuoted() {
            assertEquals("\"Notts, County\"",
                    CsvStandingsWriter.escapeCsvField("Notts, County"));
        }

        @Test
        @DisplayName("name with double-quote has quotes doubled and is wrapped")
        void nameWithDoubleQuoteIsEscaped() {
            assertEquals("\"Say \"\"hello\"\" FC\"",
                    CsvStandingsWriter.escapeCsvField("Say \"hello\" FC"));
        }

        @Test
        @DisplayName("name with newline is wrapped in quotes")
        void nameWithNewlineIsQuoted() {
            assertEquals("\"Line1\nLine2\"",
                    CsvStandingsWriter.escapeCsvField("Line1\nLine2"));
        }

        @Test
        @DisplayName("empty string needs no escaping")
        void emptyStringUnchanged() {
            assertEquals("", CsvStandingsWriter.escapeCsvField(""));
        }
    }

    // -------------------------------------------------------------------------
    // formatRow (unit tests for the static helper)
    // -------------------------------------------------------------------------

    @Nested
    @DisplayName("formatRow")
    class FormatRow {

        @Test
        @DisplayName("column order: position,team,played,won,drawn,lost,gf,ga,avg,points")
        void columnOrderIsCorrect() {
            // Arsenal beat Opponent 3-1: W=1, GF=3, GA=1, Pts=2, avg=3.000
            TeamStanding s = standingFor("Arsenal", 3, 1);
            String row = CsvStandingsWriter.formatRow(1, s);

            // Split on commas (no quoted commas in this row)
            String[] cols = row.split(",");
            assertEquals("1",       cols[0], "position");
            assertEquals("Arsenal", cols[1], "team");
            assertEquals("1",       cols[2], "played");
            assertEquals("1",       cols[3], "won");
            assertEquals("0",       cols[4], "drawn");
            assertEquals("0",       cols[5], "lost");
            assertEquals("3",       cols[6], "goals_for");
            assertEquals("1",       cols[7], "goals_against");
            assertEquals("3.000",   cols[8], "goal_average");
            assertEquals("2",       cols[9], "points");
        }

        @Test
        @DisplayName("team name with comma is properly escaped in the row")
        void teamNameWithCommaIsEscapedInRow() {
            // Build a standing directly to avoid MatchResult validation rejecting a comma name.
            // We use a plain name through the calculator, then test escapeCsvField separately.
            // Here we test that formatRow delegates to escapeCsvField correctly.
            String row = CsvStandingsWriter.formatRow(1, standingFor("Arsenal", 2, 1));
            // Simple check: row starts with "1,Arsenal,"
            assertTrue(row.startsWith("1,Arsenal,"),
                    "Row must start with position and team name");
        }

        @Test
        @DisplayName("goal average is empty when GA is zero")
        void goalAverageIsEmptyForZeroGA() {
            // Arsenal beat Opponent 1-0: GA=0 → avg=∞ → empty field
            TeamStanding s = standingFor("Arsenal", 1, 0);
            String row = CsvStandingsWriter.formatRow(1, s);

            // Row: "1,Arsenal,1,1,0,0,1,0,,2"
            // The goal_average column (index 8) must be empty — two consecutive commas.
            assertTrue(row.contains(",,"),
                    "Row must contain empty goal_average field (two consecutive commas) " +
                    "when GA=0. Row was: " + row);
        }
    }

    // -------------------------------------------------------------------------
    // File output
    // -------------------------------------------------------------------------

    @Nested
    @DisplayName("file output")
    class FileOutput {

        @Test
        @DisplayName("header row is the first line")
        void headerIsFirstLine() throws Exception {
