        $content = Get-Content $fullPath -Raw -ErrorAction SilentlyContinue
        foreach ($pat in $patterns) {
            if ($content -match $pat) {
                Write-Host "POTENTIAL SECRET in $file : pattern '$pat'"
            }
        }
    }
}
Write-Host "Secret scan complete."

