Write-Host "`n=== Stale org/example directory ==="
$orgPath = "c:\Users\Mshega\Documents\Projects\football-league-standings\src\main\java\org"
if (Test-Path $orgPath) {
    $contents = Get-ChildItem -Recurse -Force $orgPath
    if ($contents.Count -eq 0) {
        Write-Host "Directory exists but is EMPTY — git will not track it. Cosmetic issue only."
    } else {
        Write-Host "WARNING: contains files:"
        $contents | Select-Object FullName
    }
} else {
    Write-Host "Directory does not exist — clean."
}

